-- =====================================================================
-- Oort Notes: SQLite schema v1
-- Hierarchy: Notebook > Chapter > Topic > Canvas
--
-- Conventions
--   * ids: TEXT (UUID, generated by the app)
--   * timestamps: INTEGER, unix epoch in milliseconds (UTC)
--   * soft delete: deleted_at IS NOT NULL means "in trash" (purged after 30 days)
--   * sizes: pixels at 96 dpi (same units tldraw uses)
--   * journal_mode = WAL and foreign_keys = ON are per-connection settings,
--     enforced by the pool config (see db.rs), NOT here: sqlx runs this file
--     inside its own transaction, so it must not contain BEGIN/COMMIT or
--     transaction-scoped pragmas.
-- Requires SQLite 3.31+ (generated columns) and FTS5 (included in rusqlite "bundled").
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. PAGE PRESETS  (predefined sizes for chapters with canvas_type = 'page')
-- ---------------------------------------------------------------------
CREATE TABLE page_presets (
  id          TEXT PRIMARY KEY,                         -- slug, e.g. 'a4-portrait'
  name        TEXT NOT NULL,                            -- 'A4 Portrait'
  category    TEXT NOT NULL CHECK (category IN ('paper', 'ratio', 'custom')),
  size_label  TEXT NOT NULL,                            -- '210 x 297 mm', '3:2'
  width       INTEGER NOT NULL CHECK (width  BETWEEN 200 AND 20000),
  height      INTEGER NOT NULL CHECK (height BETWEEN 200 AND 20000),
  orientation TEXT GENERATED ALWAYS AS (
                CASE WHEN width > height THEN 'landscape'
                     WHEN width < height THEN 'portrait'
                     ELSE 'square' END
              ) VIRTUAL,
  is_builtin  INTEGER NOT NULL DEFAULT 0 CHECK (is_builtin IN (0, 1)),
  sort_order  INTEGER NOT NULL DEFAULT 0,
  created_at  INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);

CREATE INDEX idx_page_presets_order ON page_presets (category, sort_order);

