-- Built-in presets cannot be edited or deleted. Custom presets (category 'custom') can.
CREATE TRIGGER page_presets_protect_update
BEFORE UPDATE ON page_presets
WHEN OLD.is_builtin = 1
BEGIN
  SELECT RAISE(ABORT, 'built-in page presets cannot be modified');
END;

CREATE TRIGGER page_presets_protect_delete
BEFORE DELETE ON page_presets
WHEN OLD.is_builtin = 1
BEGIN
  SELECT RAISE(ABORT, 'built-in page presets cannot be deleted');
END;

-- ---------------------------------------------------------------------
-- 2. NOTEBOOKS
-- ---------------------------------------------------------------------
CREATE TABLE notebooks (
  id             TEXT PRIMARY KEY,
  name           TEXT NOT NULL CHECK (length(trim(name)) > 0),
  label          TEXT,                                  -- short cover label, e.g. 'PHYSICS'
  description    TEXT,
  icon           TEXT,                                  -- icon key from the app's icon set
  is_favorite    INTEGER NOT NULL DEFAULT 0 CHECK (is_favorite IN (0, 1)),
  position       INTEGER NOT NULL DEFAULT 0,            -- manual order on the home screen
  last_opened_at INTEGER,
  archived_at    INTEGER,                               -- NULL = not archived
  created_at     INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at     INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  deleted_at     INTEGER                                -- NULL = not in trash
);

CREATE UNIQUE INDEX uq_notebooks_name     ON notebooks (name COLLATE NOCASE) WHERE deleted_at IS NULL;
CREATE INDEX        idx_notebooks_order   ON notebooks (position)            WHERE deleted_at IS NULL;
CREATE INDEX        idx_notebooks_recent  ON notebooks (last_opened_at DESC) WHERE deleted_at IS NULL;

-- ---------------------------------------------------------------------
-- 3. CHAPTERS  (the canvas type and its settings live here)
-- ---------------------------------------------------------------------
CREATE TABLE chapters (
  id             TEXT PRIMARY KEY,
  notebook_id    TEXT NOT NULL REFERENCES notebooks (id) ON DELETE CASCADE,
  name           TEXT NOT NULL CHECK (length(trim(name)) > 0),
  canvas_type    TEXT NOT NULL CHECK (canvas_type IN ('infinite', 'page', 'scroll')),

  -- canvas_type = 'page': size is copied from the preset (or entered as custom) so a
  -- chapter never changes if a custom preset is edited or deleted later.
  page_preset_id TEXT REFERENCES page_presets (id) ON DELETE SET NULL,
  page_width     INTEGER CHECK (page_width  BETWEEN 200 AND 20000),
  page_height    INTEGER CHECK (page_height BETWEEN 200 AND 20000),

  -- canvas_type = 'scroll': fixed width, unlimited height
  scroll_width   INTEGER CHECK (scroll_width BETWEEN 320 AND 4000),

  background     TEXT NOT NULL DEFAULT 'plain' CHECK (background IN ('plain', 'dots', 'grid', 'ruled')),
  position       INTEGER NOT NULL DEFAULT 0,            -- order inside the notebook
  created_at     INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at     INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  deleted_at     INTEGER,

  -- page needs a size; every other type must not carry one
  CHECK (
    (canvas_type = 'page'
       AND page_width IS NOT NULL AND page_height IS NOT NULL)
    OR
    (canvas_type <> 'page'
       AND page_preset_id IS NULL AND page_width IS NULL AND page_height IS NULL)
  ),
  -- scroll needs a width; every other type must not carry one
  CHECK (
    (canvas_type = 'scroll' AND scroll_width IS NOT NULL)
    OR
    (canvas_type <> 'scroll' AND scroll_width IS NULL)
  )
);

CREATE UNIQUE INDEX uq_chapters_name   ON chapters (notebook_id, name COLLATE NOCASE) WHERE deleted_at IS NULL;
CREATE INDEX        idx_chapters_order ON chapters (notebook_id, position)            WHERE deleted_at IS NULL;

-- Canvas type and size are locked as soon as the chapter has any topic.
CREATE TRIGGER chapters_lock_canvas
BEFORE UPDATE OF canvas_type, page_preset_id, page_width, page_height, scroll_width ON chapters
WHEN EXISTS (SELECT 1 FROM topics WHERE chapter_id = OLD.id)
 AND (   NEW.canvas_type    IS NOT OLD.canvas_type
      OR NEW.page_preset_id IS NOT OLD.page_preset_id
      OR NEW.page_width     IS NOT OLD.page_width
      OR NEW.page_height    IS NOT OLD.page_height
      OR NEW.scroll_width   IS NOT OLD.scroll_width)
BEGIN
  SELECT RAISE(ABORT, 'canvas type is locked once a chapter has topics');
END;

-- ---------------------------------------------------------------------
-- 4. TOPICS  (light rows; the heavy canvas JSON lives in topic_canvas)
-- ---------------------------------------------------------------------
CREATE TABLE topics (
  id             TEXT PRIMARY KEY,
  chapter_id     TEXT NOT NULL REFERENCES chapters (id) ON DELETE CASCADE,
  name           TEXT NOT NULL CHECK (length(trim(name)) > 0),
  position       INTEGER NOT NULL DEFAULT 0,
  is_pinned      INTEGER NOT NULL DEFAULT 0 CHECK (is_pinned IN (0, 1)),
  last_opened_at INTEGER,
  created_at     INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at     INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  deleted_at     INTEGER
);

CREATE UNIQUE INDEX uq_topics_name   ON topics (chapter_id, name COLLATE NOCASE) WHERE deleted_at IS NULL;
CREATE INDEX        idx_topics_order ON topics (chapter_id, position)            WHERE deleted_at IS NULL;
CREATE INDEX        idx_topics_recent ON topics (last_opened_at DESC)            WHERE deleted_at IS NULL;

-- ---------------------------------------------------------------------
-- 5. TOPIC CANVAS  (one row per topic: tldraw snapshot + metadata)
-- ---------------------------------------------------------------------
CREATE TABLE topic_canvas (
  topic_id        TEXT PRIMARY KEY REFERENCES topics (id) ON DELETE CASCADE,
  snapshot        TEXT NOT NULL DEFAULT '{}',           -- JSON from getSnapshot(editor.store)
  snapshot_format INTEGER NOT NULL DEFAULT 1,           -- bump when the app changes how it stores snapshots
  tldraw_version  TEXT,                                 -- tldraw version that wrote the snapshot
  shape_count     INTEGER NOT NULL DEFAULT 0,
  byte_size       INTEGER NOT NULL DEFAULT 0,           -- length of snapshot in bytes
  content_height  INTEGER,                              -- scroll chapters: current grown height
  camera_x        REAL NOT NULL DEFAULT 0,              -- restore the last view on open
  camera_y        REAL NOT NULL DEFAULT 0,
  camera_zoom     REAL NOT NULL DEFAULT 1 CHECK (camera_zoom > 0),
  saved_at        INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);

-- Every new topic gets its (empty) canvas automatically.
CREATE TRIGGER topics_create_canvas
AFTER INSERT ON topics
BEGIN
  INSERT INTO topic_canvas (topic_id) VALUES (NEW.id);
END;

-- Saving the canvas marks the topic, chapter and notebook as edited.
CREATE TRIGGER topic_canvas_touch
AFTER UPDATE OF snapshot ON topic_canvas
BEGIN
  UPDATE topic_canvas SET saved_at = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)
   WHERE topic_id = NEW.topic_id;
  UPDATE topics    SET updated_at = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)
   WHERE id = NEW.topic_id;
  UPDATE chapters  SET updated_at = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)
   WHERE id = (SELECT chapter_id FROM topics WHERE id = NEW.topic_id);
  UPDATE notebooks SET updated_at = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)
   WHERE id = (SELECT c.notebook_id FROM chapters c
                 JOIN topics t ON t.chapter_id = c.id WHERE t.id = NEW.topic_id);
END;

-- Adding, renaming, moving or trashing a topic marks its chapter and notebook as edited.
CREATE TRIGGER topics_touch_parents
AFTER UPDATE OF name, chapter_id, deleted_at ON topics
BEGIN
  UPDATE chapters  SET updated_at = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)
   WHERE id = NEW.chapter_id;
  UPDATE notebooks SET updated_at = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)
   WHERE id = (SELECT notebook_id FROM chapters WHERE id = NEW.chapter_id);
END;

CREATE TRIGGER topics_touch_parents_insert
AFTER INSERT ON topics
BEGIN
  UPDATE chapters  SET updated_at = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)
   WHERE id = NEW.chapter_id;
  UPDATE notebooks SET updated_at = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)
   WHERE id = (SELECT notebook_id FROM chapters WHERE id = NEW.chapter_id);
END;

-- ---------------------------------------------------------------------
-- 6. TAGS  (optional metadata on topics)
-- ---------------------------------------------------------------------
CREATE TABLE tags (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL CHECK (length(trim(name)) > 0),
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);
CREATE UNIQUE INDEX uq_tags_name ON tags (name COLLATE NOCASE);

CREATE TABLE topic_tags (
  topic_id TEXT NOT NULL REFERENCES topics (id) ON DELETE CASCADE,
  tag_id   TEXT NOT NULL REFERENCES tags (id)   ON DELETE CASCADE,
  PRIMARY KEY (topic_id, tag_id)
) WITHOUT ROWID;
CREATE INDEX idx_topic_tags_tag ON topic_tags (tag_id);

-- ---------------------------------------------------------------------
-- 7. SEARCH  (powers the Cmd+K search; the app fills it)
--    kind: 'notebook' | 'chapter' | 'topic'
--    body: text extracted from the topic's text shapes (optional)
-- ---------------------------------------------------------------------
CREATE VIRTUAL TABLE search_fts USING fts5 (
  kind UNINDEXED,
  ref_id UNINDEXED,
  title,
  body,
  tokenize = 'unicode61 remove_diacritics 2'
);

-- ---------------------------------------------------------------------
-- 8. SETTINGS  (key/value) and BACKUPS (Google Drive history)
-- ---------------------------------------------------------------------
CREATE TABLE settings (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,
  updated_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
) WITHOUT ROWID;

INSERT INTO settings (key, value) VALUES
  ('backup_enabled',        '1'),
  ('backup_interval_days',  '7'),
  ('backup_keep_count',     '4'),
  ('last_backup_at',        ''),
  ('trash_retention_days',  '30'),
  ('sidebar_collapsed',     '0'),
  ('default_page_preset',   'a4-portrait'),
  ('default_scroll_width',  '800');

CREATE TABLE backups (
  id            TEXT PRIMARY KEY,
  file_name     TEXT NOT NULL,                          -- 'backup-2026-10-05.zip'
  drive_file_id TEXT,                                   -- Google Drive file id once uploaded
  size_bytes    INTEGER,
  status        TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'uploaded', 'failed', 'deleted')),
  error         TEXT,
  created_at    INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  uploaded_at   INTEGER
);
CREATE INDEX idx_backups_created ON backups (created_at DESC);

-- ---------------------------------------------------------------------
-- 9. VIEWS  (what the UI actually lists; trash is filtered out)
-- ---------------------------------------------------------------------
CREATE VIEW v_notebooks AS
SELECT n.id, n.name, n.label, n.description, n.icon, n.is_favorite, n.position,
       n.last_opened_at, n.archived_at, n.created_at,
       (SELECT COUNT(*) FROM chapters c
         WHERE c.notebook_id = n.id AND c.deleted_at IS NULL) AS chapter_count,
       (SELECT COUNT(*) FROM topics t JOIN chapters c ON c.id = t.chapter_id
         WHERE c.notebook_id = n.id AND c.deleted_at IS NULL AND t.deleted_at IS NULL) AS topic_count,
       n.updated_at AS last_edited_at
FROM notebooks n
WHERE n.deleted_at IS NULL;

CREATE VIEW v_chapters AS
SELECT c.id, c.notebook_id, c.name, c.canvas_type, c.page_preset_id,
       c.page_width, c.page_height, c.scroll_width, c.background, c.position, c.created_at,
       p.name AS page_preset_name,
       (SELECT COUNT(*) FROM topics t
         WHERE t.chapter_id = c.id AND t.deleted_at IS NULL) AS topic_count,
       EXISTS (SELECT 1 FROM topics t WHERE t.chapter_id = c.id) AS is_locked,
       c.updated_at AS last_edited_at
FROM chapters c
JOIN notebooks n ON n.id = c.notebook_id AND n.deleted_at IS NULL
LEFT JOIN page_presets p ON p.id = c.page_preset_id
WHERE c.deleted_at IS NULL;

-- Everything the editor needs to open a topic, except the snapshot itself.
CREATE VIEW v_topics AS
SELECT t.id, t.chapter_id, t.name, t.position, t.is_pinned, t.last_opened_at,
       t.created_at, t.updated_at AS last_edited_at,
       c.notebook_id, c.canvas_type, c.page_width, c.page_height, c.scroll_width, c.background,
       k.shape_count, k.byte_size, k.content_height,
       k.camera_x, k.camera_y, k.camera_zoom, k.saved_at
FROM topics t
JOIN chapters c ON c.id = t.chapter_id AND c.deleted_at IS NULL
JOIN notebooks n ON n.id = c.notebook_id AND n.deleted_at IS NULL
LEFT JOIN topic_canvas k ON k.topic_id = t.id
WHERE t.deleted_at IS NULL;

CREATE VIEW v_trash AS
SELECT 'notebook' AS kind, id, name, NULL AS parent_id, deleted_at,
       deleted_at + CAST((SELECT value FROM settings WHERE key = 'trash_retention_days') AS INTEGER) * 86400000 AS purge_at
  FROM notebooks WHERE deleted_at IS NOT NULL
UNION ALL
SELECT 'chapter', id, name, notebook_id, deleted_at,
       deleted_at + CAST((SELECT value FROM settings WHERE key = 'trash_retention_days') AS INTEGER) * 86400000
  FROM chapters WHERE deleted_at IS NOT NULL
UNION ALL
SELECT 'topic', id, name, chapter_id, deleted_at,
       deleted_at + CAST((SELECT value FROM settings WHERE key = 'trash_retention_days') AS INTEGER) * 86400000
  FROM topics WHERE deleted_at IS NOT NULL;

PRAGMA user_version = 1;   -- increment with every migration
